const users = $('NL Filter Due').all();
const results = [];
let i = 0;

for (const item of $input.all()) {
  const raw = item.json.text || "";
  let clean = raw.replace(/```json/g, "").replace(/```/g, "").trim();

  // keep only from first [ to last ]
  const start = clean.indexOf("[");
  const end = clean.lastIndexOf("]");
  if (start !== -1 && end !== -1 && end > start) {
    clean = clean.slice(start, end + 1);
  } else if (start !== -1) {
    clean = clean.slice(start);
  }

  let articles = null;
  try {
    articles = JSON.parse(clean);
  } catch (e) {
    // fallback: truncated JSON -> close after last complete object
    const lastBrace = clean.lastIndexOf("}");
    if (lastBrace !== -1) {
      try {
        articles = JSON.parse(clean.slice(0, lastBrace + 1) + "]");
      } catch (e2) {
        articles = null;
      }
    }
  }

  // skip this user if LLM output is unusable (don't crash the others)
  if (!articles || !Array.isArray(articles) || articles.length === 0) {
    i++;
    continue;
  }

  const articlesHtml = articles.map(a =>
    "<div style='margin-bottom:20px'>"
    + "<h3 style='margin-bottom:4px'>" + (a.title || "") + "</h3>"
    + "<p style='margin:4px 0'>" + (a.summary || "") + "</p>"
    + "<a href='" + (a.link || "#") + "'>Lire l'article</a>"
    + "</div>"
  ).join("");

  const html = "<h1>Votre veille climat du jour</h1>"
    + articlesHtml
    + "<hr>"
    + "<p style='color:gray;font-size:12px'>Vous recevez cet email car vous êtes inscrit à Persona. "
    + "<a href='http://localhost:5678/form/7563b672-5325-4bad-a636-391f23f2eb61'>Cliquez ici pour vous désabonner</a>.</p>";

  results.push({
    json: {
      html: html,
      email: users[i] ? users[i].json.email : undefined,
      sessionId: users[i] ? users[i].json.sessionId : undefined
    }
  });

  i++;
}

return results;
